!function(window){"use strict";const CHROME_AI_SUPPORTED_LANGUAGES=["ar","bg","bn","cs","da","de","el","en","es","fi","fr","hi","hr","hu","id","it","iw","ja","kn","ko","lt","mr","nl","no","pl","pt","ro","ru","sk","sl","sv","ta","te","th","tr","uk","vi","zh","zh-hant"],ChromeLanguages={getAll:()=>CHROME_AI_SUPPORTED_LANGUAGES,formatCode(langCode){if(!langCode||"string"!=typeof langCode)return"en";const clean=langCode.trim().toLowerCase().replace("_","-");return"he"===clean?"iw":"nb"===clean||"nn"===clean?"no":"zh-cn"===clean||"zh-hans"===clean?"zh":clean.split("-")[0]},isSupported(langCode){if(!langCode)return!1;const formatted=this.formatCode(langCode);return CHROME_AI_SUPPORTED_LANGUAGES.includes(formatted)}};window.TranslateSenseChromeLanguages=ChromeLanguages}(window);